import React, { useState, useEffect } from "react";
import { Link } from "react-router-dom";
import "./navbar.css";

export default function Navbar({ isLogin, onLogout }) {
  const [menuOpen, setMenuOpen] = useState(false);
  const [profileOpen, setProfileOpen] = useState(false);
  const [loginDropdown, setLoginDropdown] = useState(false);

  const email = localStorage.getItem("email");
  const role = localStorage.getItem("role");
  const [name, setName] = useState("");

  useEffect(() => {
    const storedName = localStorage.getItem("name");
    if (storedName) setName(storedName);
  }, []);

  const firstLetter = name ? name.charAt(0).toUpperCase() : "U";

  return (
    <nav style={styles.navbar}>
      <Link to="/" style={styles.logo}>DailyCode</Link>

      <ul style={styles.navLinks}>
        {!isLogin ? (
          <li style={{ position: "relative" }}>
            <span
              style={styles.link}
              onClick={() => setLoginDropdown(!loginDropdown)}
            >
              Login ▾
            </span>

            {loginDropdown && (
              <div style={styles.dropdown}>
                <Link to="/login" style={styles.dropdownLink}>
                  👤 User Login
                </Link>

                <Link to="/admin/login" style={styles.dropdownLink}>
                  🛠 Admin Login
                </Link>
              </div>
            )}
          </li>
        ) : (
          <li style={{ position: "relative" }}>
            <div
              style={styles.avatar}
              onClick={() => setProfileOpen(!profileOpen)}
            >
              {firstLetter}
            </div>

            {profileOpen && (
              <div style={styles.dropdown}>
                <p>{name}</p>
                <p>{email}</p>

                {role === "admin" && (
                  <Link to="/admin/dashboard" style={styles.dropdownLink}>
                    🛠 Admin Dashboard
                  </Link>
                )}

                <button style={styles.logoutBtn} onClick={onLogout}>
                  Logout
                </button>
              </div>
            )}
          </li>
        )}
      </ul>
    </nav>
  );
}

const styles = {
  navbar: {
    height: "70px",
    background: "#0f172a",
    color: "white",
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
    padding: "0 20px",
  },
  logo: {
    color: "#38bdf8",
    fontSize: "22px",
    textDecoration: "none",
  },
  navLinks: {
    listStyle: "none",
  },
  link: {
    cursor: "pointer",
  },
  avatar: {
    background: "#38bdf8",
    width: "35px",
    height: "35px",
    borderRadius: "50%",
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    cursor: "pointer",
  },
  dropdown: {
    position: "absolute",
    top: "45px",
    right: 0,
    background: "#020617",
    padding: "10px",
  },
  dropdownLink: {
    display: "block",
    color: "white",
    textDecoration: "none",
    padding: "5px",
  },
  logoutBtn: {
    marginTop: "10px",
    width: "100%",
  },
};
